export const nav = [
  { id: 'now', label: 'Now' },
  { id: 'background', label: 'Background' },
  { id: 'projects', label: 'Projects' },
  { id: 'skills', label: 'Skills' },
  { id: 'interests', label: 'Interests' },
  { id: 'contact', label: 'Contact' },
];

export const hero = {
  eyebrow: 'Chetanya Makkar',
  title: "I build the things between an idea and a dashboard.",
  subtitle:
    "CS grad from the University of Maryland (Computational Finance minor). I like shipping software, reading markets, and turning messy data into decisions — usually with a half-finished side project running in another tab.",
  badges: [
    { label: 'Product, Analytics & Strategy @ VenHub', tone: 'primary' },
    { label: 'UMD ’26 · CS + Computational Finance', tone: 'neutral' },
    { label: 'Open to interesting conversations', tone: 'success' },
  ],
  terminalLines: [
    'whoami',
    '> engineer, quant-curious, product-minded, startup-bound',
  ],
  primaryCta: { label: 'See what I’m building', href: '#projects' },
  secondaryCta: { label: 'Get in touch', href: '#contact' },
};

export const now = {
  eyebrow: '// now',
  heading: 'What I’m up to',
  current: {
    badge: 'Current · starting June 2026',
    title: 'Product, Analytics & Strategy Analyst @ VenHub',
    description:
      "VenHub is a Pasadena-based startup building fully autonomous, AI-powered robotic retail stores — think staffless smart stores you can order from and pick up in minutes. I’m joining full-time to work across product, analytics, and strategy as the company scales toward a nationwide rollout.",
    tags: ['Product', 'Analytics', 'Strategy', 'AI x Retail', 'Startups'],
  },
  threads: [
    {
      icon: 'Compass',
      title: 'Exploring',
      description:
        'Quant trading strategies, market microstructure, and how systematic funds actually think about risk.',
    },
    {
      icon: 'Hammer',
      title: 'Building',
      description:
        'Small AI-assisted tools and dashboards — mostly to answer my own "what would happen if..." questions.',
    },
    {
      icon: 'Lightbulb',
      title: 'Thinking about',
      description:
        'How early-stage product teams use data to decide what to build next, and how to make that loop faster.',
    },
  ],
};

export const background = {
  eyebrow: '// background',
  heading: 'The resume version',
  education: {
    school: 'University of Maryland, College Park',
    degree: 'B.S. Computer Science',
    minor: 'Minor in Computational Finance',
    gpa: '3.76 / 4.0',
  },
  previously: [
    { company: 'BuzzClan', role: 'Software Engineering Intern' },
    { company: 'WSQ', role: 'Quantitative Researcher' },
    { company: 'UMD Climate Computing Lab', role: 'Undergraduate Researcher' },
    { company: 'University of Maryland', role: 'Teaching Assistant' },
    { company: 'Ruhin Education', role: 'Co-Founder' },
  ],
  note: 'Full role-by-role history, dates, and recommendations live on LinkedIn.',
  cta: { label: 'View full experience on LinkedIn', href: 'https://www.linkedin.com/in/chetanyamakkar/' },
};

// category keys used for filtering
export const projectCategories = [
  { id: 'all', label: 'All' },
  { id: 'swe', label: 'Software' },
  { id: 'quant', label: 'Quant & Finance' },
  { id: 'data', label: 'Data & Analytics' },
];

export const projects = [
  {
    title: 'Portfolio Optimization Engine',
    categories: ['quant'],
    status: 'Personal project',
    problem:
      'Naive equal-weight portfolios leave return on the table relative to what historical data implies is achievable.',
    build:
      'An optimizer that constructs portfolios for maximum Sharpe ratio or minimum risk from historical return data, including data cleaning, covariance estimation, and backtesting.',
    tech: ['Python', 'NumPy', 'Pandas', 'cvxpy', 'Matplotlib'],
    impact: 'Improved annualized Sharpe ratio by ~25% over a naive equal-weight strategy in backtests.',
  },
  {
    title: 'Option Pricing Models',
    categories: ['quant'],
    status: 'Personal project',
    problem:
      'Wanted a hands-on way to compare theoretical option prices against real market quotes.',
    build:
      'Implemented Black-Scholes and binomial tree pricing models for European and American options, then validated outputs against live market data.',
    tech: ['Python', 'SciPy', 'NumPy', 'Financial Math'],
    impact: 'Achieved high pricing accuracy and built practical intuition for derivatives valuation and numerical convergence.',
  },
  {
    title: 'Flash Crash Analysis',
    categories: ['quant', 'data'],
    status: 'Research project',
    problem:
      'The 2010 Flash Crash is a classic case study in market fragility, but the underlying order-flow story is buried in raw tick data.',
    build:
      'Cleaned and analyzed large tick-by-tick trade and quote datasets, synced timestamps across exchanges, and built visual timelines and volatility profiles.',
    tech: ['Python', 'Pandas', 'Plotly', 'Market Microstructure'],
    impact: 'Surfaced insights into high-frequency trading triggers and liquidity-vacuum effects during the crash.',
  },
  {
    title: 'Bond Yield Curve Regression',
    categories: ['quant'],
    status: 'Coursework project',
    problem:
      'Yield curve shape shifts carry signal about rate expectations, but raw Treasury data is irregular and noisy.',
    build:
      'Fit Nelson-Siegel curves to U.S. Treasury data and decomposed movements into level, slope, and curvature factors over time.',
    tech: ['Python', 'scikit-learn', 'NumPy', 'Pandas', 'Statsmodels'],
    impact: 'Improved predictive accuracy of forward rates and duration modeling while managing overfitting on irregular intervals.',
  },
  {
    title: 'Maze Solver (Dijkstra + Java UI)',
    categories: ['swe'],
    status: 'Coursework project',
    problem:
      'Graph algorithms are easier to internalize when you can watch them run.',
    build:
      'A Java desktop app that visualizes shortest-path search through a maze in real time using Dijkstra’s algorithm, with a custom Swing UI for live updates.',
    tech: ['Java', 'Swing', 'Graph Algorithms', 'OOP'],
    impact: 'Reinforced graph theory fundamentals and shipped a responsive UI that stays smooth on larger mazes.',
  },
  {
    title: 'FSM Vending Machine',
    categories: ['swe'],
    status: 'Coursework project',
    problem:
      'Modeling stateful systems cleanly is a classic systems-design problem.',
    build:
      'A finite-state-machine simulation of a vending machine in Rust, modeling coin inputs, product selection, and state transitions with enums and pattern matching.',
    tech: ['Rust', 'FSMs', 'Enums', 'Pattern Matching', 'Cargo'],
    impact: 'Strengthened state-machine design skills and hands-on use of Rust’s memory-safe type system.',
  },
  {
    title: 'MicroOCaml Optimizer & Type Checker',
    categories: ['swe'],
    status: 'Coursework project',
    problem:
      'Optimizing compilers need correct type rules before any optimization pass can be trusted.',
    build:
      'A type-checker and optimizer for a small OCaml-like language, including constant folding, dead-code elimination, and recursive type inference rules.',
    tech: ['OCaml', 'Parsers', 'Functional Programming', 'Type Inference'],
    impact: 'Reduced runtime complexity of user-written test programs while preserving program correctness.',
  },
  {
    title: 'Solar Power Generation Study',
    categories: ['data'],
    status: 'Award-winning project',
    problem:
      'Solar generation data from multiple sensors had missing timestamps and inconsistent frequency, masking real efficiency patterns.',
    build:
      'Processed multi-sensor time-series data, visualized generation patterns, and identified peak hours and degradation trends.',
    tech: ['Python', 'Pandas', 'Matplotlib', 'Seaborn'],
    impact: 'Won an award for data storytelling and helped the partner organization identify panel degradation.',
  },
  {
    title: 'GPA Analysis',
    categories: ['data'],
    status: 'Personal project',
    problem:
      'Curious whether extracurriculars, major, and credit load actually correlate with GPA outcomes — or if it’s mostly noise.',
    build:
      'Ran exploratory data analysis, regression, and hypothesis testing on student GPA data while accounting for outliers and self-reporting bias.',
    tech: ['Python', 'Seaborn', 'NumPy', 'Statsmodels'],
    impact: 'Surfaced trends useful for academic advising and workload planning conversations.',
  },
];

export const skillGroups = [
  {
    title: 'Languages',
    icon: 'Code2',
    items: ['Python', 'Java', 'Rust', 'OCaml', 'SQL', 'R'],
  },
  {
    title: 'Frameworks & Libraries',
    icon: 'Blocks',
    items: ['React', 'Tailwind CSS', 'Node.js', 'scikit-learn', 'PyTorch', 'TensorFlow'],
  },
  {
    title: 'Tools & Platforms',
    icon: 'Wrench',
    items: ['Git / GitHub', 'Jupyter', 'Excel (VBA)', 'LaTeX', 'VS Code', 'PowerPoint'],
  },
  {
    title: 'Finance & Quant',
    icon: 'LineChart',
    items: [
      'Portfolio & Risk Optimization',
      'Option Pricing (Black-Scholes, Monte Carlo)',
      'Fixed Income & Yield Curves',
      'Backtesting & Market Microstructure',
    ],
  },
  {
    title: 'Data Science',
    icon: 'BarChart3',
    items: [
      'Regression & Statistical Analysis',
      'A/B Testing & Experimentation',
      'Data Visualization',
      'Data Cleaning & Time Series',
    ],
  },
];

export const interests = {
  eyebrow: '// interests',
  heading: 'Systems I think about',
  cards: [
    {
      icon: 'TrendingUp',
      title: 'Markets & Quant',
      description:
        'How prices, risk, and incentives interact — from option pricing to why a yield curve inverts. Half-finished backtests are basically my comfort food.',
    },
    {
      icon: 'Sparkles',
      title: 'AI & Applied ML',
      description:
        'Less interested in chasing benchmarks, more interested in wiring models into products and workflows that save people real time.',
    },
    {
      icon: 'BarChart3',
      title: 'Product & Growth Analytics',
      description:
        'Dashboards, funnels, experiments. Turning "I think users do X" into "here’s the data, here’s what we should ship next."',
    },
    {
      icon: 'Rocket',
      title: 'Startups & Internal Tools',
      description:
        'Small teams, fast iteration, and the unglamorous internal tools that quietly make everything else work.',
    },
  ],
};

export const contact = {
  eyebrow: '// contact',
  heading: "Let's build something",
  description:
    "Whether it's a role, a project, or just a good conversation about markets, products, or AI — my inbox is open.",
  links: {
    email: 'chetanyamakkar99@gmail.com',
    linkedin: 'https://www.linkedin.com/in/chetanyamakkar/',
    github: 'https://github.com/chetanyamakkar11',
    resume: 'https://drive.google.com/file/d/1wSHQUrUyCmEIYzn30n9mgJyTx0ZtrSaL/view?usp=sharing',
  },
};
